#!/bin/sh
# Rewrite Sources/Hukan/WindowsCatalog.swift from the newest Windows 11 catalog Microsoft's Media
# Creation Tool reads: the ARM64 consumer image (Home and Pro, one ESD) in each language, with the
# address Microsoft serves it from and the SHA-256 Microsoft states for it.
#
# Microsoft's own link (go.microsoft.com/fwlink/?LinkId=2156292) stopped at 24H2. Newer catalogs
# are found through Windows on R's index (worproject.com/dldserv/esd/getversions.php), which also
# hosts some of them — so nothing in a catalog is taken until its Authenticode signature checks out
# against Microsoft's root, pinned here by fingerprint: the index only says where to look, and the
# app itself never asks it anything. Needs osslsigncode (Homebrew). Rerun for a new release, read
# the diff, commit.
set -eu

HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/../Sources/Hukan/WindowsCatalog.swift"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

CODE_ROOT=847DF6A78497943F27FC72EB93F9A637320A02B561D0A91B09E87A7807ED7C61
TIMESTAMP_ROOT=DF545BF919A2439C36983B54CDFC903DFA4F37D3996D8D84B4C31EEC6F3C163E

root() {
  curl -fsSL -o "$WORK/root.crt" "$1"
  print=$(openssl x509 -inform DER -in "$WORK/root.crt" -noout -fingerprint -sha256 \
    | sed 's/.*=//; s/://g')
  [ "$print" = "$2" ] || { echo "Root at $1 is not the pinned one ($print)" >&2; exit 1; }
  openssl x509 -inform DER -in "$WORK/root.crt" >> "$WORK/roots.pem"
}
root https://www.microsoft.com/pki/certs/MicRooCerAut2011_2011_03_22.crt "$CODE_ROOT"
root https://www.microsoft.com/pki/certs/MicRooCerAut_2010-06-23.crt "$TIMESTAMP_ROOT"

curl -fsSL -o "$WORK/versions.xml" https://worproject.com/dldserv/esd/getversions.php
set -- $(python3 -I - "$WORK/versions.xml" <<'EOF'
import sys, xml.etree.ElementTree as ET
version = ET.parse(sys.argv[1]).find("./versions/version[@number='11']")
release = max(version.iter("release"), key=lambda r: r.findtext("date"))
print(release.get("build"), release.findtext("date"), release.findtext("cabLink"))
EOF
)
BUILD=$1 DATE=$2 CAB=$3
echo "Windows 11 $BUILD of $DATE: $CAB"

curl -fsSL -o "$WORK/products.cab" "$CAB"
osslsigncode verify -in "$WORK/products.cab" -CAfile "$WORK/roots.pem" \
  -TSA-CAfile "$WORK/roots.pem" > "$WORK/verify.log" 2>&1 \
  || { cat "$WORK/verify.log" >&2; echo "The catalog's signature did not verify" >&2; exit 1; }
grep -q "CN=Microsoft Corporation" "$WORK/verify.log" \
  || { echo "The catalog is not signed by Microsoft Corporation" >&2; exit 1; }
(cd "$WORK" && tar -xf products.cab products.xml)

python3 -I - "$WORK/products.xml" "$BUILD" "$DATE" > "$OUT" <<'EOF'
import sys, xml.etree.ElementTree as ET
path, build, date = sys.argv[1:]
images = {}
for f in ET.parse(path).iter("File"):
    name = f.findtext("FileName") or ""
    if f.findtext("Architecture") != "ARM64" or "CLIENTCONSUMER_RET_A64FRE" not in name:
        continue
    images[f.findtext("LanguageCode")] = (
        f.findtext("Language"), f.findtext("FilePath"), int(f.findtext("Size")),
        f.findtext("Sha256").lower())
assert images, "no ARM64 consumer images in the catalog"
date = f"{date[:4]}-{date[4:6]}-{date[6:]}"
print("// Generated by Vendor/update-windows-catalog.sh from Microsoft's signed ESD catalog; rerun")
print("// it rather than editing this file.")
print()
print("enum WindowsCatalog {")
print(f'  static let build = "{build}"')
print(f'  static let published = "{date}"')
print("  static let images: [WindowsImage] = [")
for code in sorted(images):
    language, url, size, sha = images[code]
    print("    WindowsImage(")
    print(f'      language: "{code}", languageName: "{language}", size: {size},')
    print(f'      sha256: "{sha}",')
    print(f'      address: "{url}"),')
print("  ]")
print("}")
EOF
xcrun swift-format format -i "$OUT"
echo "$(grep -c 'WindowsImage(' "$OUT") languages written to $OUT"
